{"settings":"{
    "explorer.confirmDragAndDrop": false,
    "workbench.editorAssociations": {
        "*.ipynb": "jupyter-notebook"
    },
    "notebook.cellToolbarLocation": {
        "default": "right",
        "jupyter-notebook": "left"
    },
    "debug.onTaskErrors": "debugAnyway",
    "security.workspace.trust.untrustedFiles": "open",
    "explorer.confirmDelete": false,
    "code-runner.runInTerminal": true,
    "notebook.output.textLineLimit": 10000,
    "jupyter.askForKernelRestart": false,
    "[cpp]": {
        "editor.defaultFormatter": "ms-vscode.cpptools"
    },
    "cmake.configureOnOpen": true,
    "terminal.integrated.enableMultiLinePasteWarning": false,
    "codesnap.realLineNumbers": true,
    "codesnap.showWindowControls": false,
    "dart.debugExternalPackageLibraries": true,
    "dart.debugSdkLibraries": true,
    "[python]": {
        "editor.formatOnType": true
    },
    "extensions.experimental.affinity": {
        "ms-toolsai.jupyter": 1,
        "ms-toolsai.jupyter-renderers": 1,
        "ms-python.python": 1,
        "ms-python.vscode-pylance": 1
    },
    "remote.tunnels.access.hostNameOverride": "Gracefield-PC",
    "terminal.integrated.inheritEnv": false,
    "editor.minimap.enabled": false,
    "editor.lineNumbers": "relative",
    "vim.leader": "<Space>",
    "vim.nohlsearch": true,
    "vim.incsearch": true,
    "vim.useSystemClipboard": true,
    "vim.normalModeKeyBindingsNonRecursive": [
        // NAVIGATION
        // switch b/w buffers
        { "before": ["<S-h>"], "commands": [":bprevious"] },
        { "before": ["<S-l>"], "commands": [":bnext"] },
        // splits
        { "before": ["leader", "v"], "commands": [":vsplit"] },
        { "before": ["leader", "s"], "commands": [":split"] },
        { "before": ["<c-h>"], "commands": [":set  hlsearch!"] },
        // panes
        {
            "before": ["leader", "h"],
            "commands": ["workbench.action.focusLeftGroup"]
        },
        {
            "before": ["leader", "e"],
            "commands": ["workbench.files.action.focusFilesExplorer"]
        },
        {
            "before": ["leader", "j"],
            "commands": ["workbench.action.focusBelowGroup"]
        },
        {
            "before": ["leader", "k"],
            "commands": ["workbench.action.focusAboveGroup"]
        },
        {
            "before": ["leader", "l"],
            "commands": ["workbench.action.focusRightGroup"]
        },
        // NICE TO HAVE
        { "before": ["leader", "w"], "commands": [":w!"] },
        { "before": ["leader", "q"], "commands": [":q!"] },
        { "before": ["leader", "x"], "commands": [":x!"] },
        {
            "before": ["[", "d"],
            "commands": ["editor.action.marker.prev"]
        },
        {
            "before": ["]", "d"],
            "commands": ["editor.action.marker.next"]
        },
        {
            "before": ["<leader>", "c", "a"],
            "commands": ["editor.action.quickFix"]
        },
        {
            "before": ["leader", "f"],
            "commands": ["workbench.action.quickOpen"]
        },
        {
            "before": ["leader", "p"],
            "commands": ["editor.action.formatDocument"]
        },
        {
            "before": ["leader", "r"],
            "commands": ["errorLens.toggleInlineMessage"]
        },
        {
            "before": ["g", "h"],
            "commands": ["editor.action.showDefinitionPreviewHover"]
        },
        { 
            "before": ["leader", "/"], 
            "commands": ["editor.action.commentLine"] 
        }
    ],
    "vim.visualModeKeyBindings": [
        // Stay in visual mode while indenting
        { "before": ["<"], "commands": ["editor.action.outdentLines"] },
        { "before": [">"], "commands": ["editor.action.indentLines"] },
        // Move selected lines while staying in visual mode
        { "before": ["J"], "commands": ["editor.action.moveLinesDownAction"] },
        { "before": ["K"], "commands": ["editor.action.moveLinesUpAction"] },
        // toggle comment selection
        { "before": ["leader", "/"], "commands": ["editor.action.commentLine"] }
    ],
    "accessibility.verbosity.notification": false,
    "window.density.editorTabHeight": "compact",
    "workbench.colorTheme": "GitHub Dark Dimmed",
    "editor.indentSize": "tabSize",
    "github.copilot.enable": {
        "*": true,
        "plaintext": false,
        "markdown": false,
        "scminput": false
    },
    "typescript.updateImportsOnFileMove.enabled": "always",
    "[typescriptreact]": {
        "editor.defaultFormatter": "vscode.typescript-language-features"
    },
    "prettier.tabWidth": 4,
    "[html]": {
        "editor.defaultFormatter": "vscode.html-language-features"
    },
    "prettier.printWidth": 150,
    "window.menuBarVisibility": "toggle",
    "errorLens.enabled": true,
    "errorLens.messageEnabled": false,
    "workbench.activityBar.location": "hidden",
    "[javascriptreact]": {
        "editor.defaultFormatter": "vscode.typescript-language-features"
    },
    "[typescript]": {
        "editor.defaultFormatter": "vscode.typescript-language-features"
    },
    "[javascript]": {
        "editor.defaultFormatter": "rvest.vs-code-prettier-eslint"
    },
    "javascript.updateImportsOnFileMove.enabled": "always",
    "notebook.lineNumbers": "on",
    "git.enableSmartCommit": true,
    "github.copilot.advanced": {},
    "[css]": {
        "editor.defaultFormatter": "esbenp.prettier-vscode"
    },
    "[dockercompose]": {
        "editor.defaultFormatter": "esbenp.prettier-vscode"
    },
    "git.confirmSync": false,
    "vs-kubernetes": {
        "vscode-kubernetes.kubectl-path-linux": "/home/blank/.local/state/vs-kubernetes/tools/kubectl/kubectl",
        "vscode-kubernetes.helm-path-linux": "/home/blank/.local/state/vs-kubernetes/tools/helm/linux-amd64/helm",
        "vscode-kubernetes.minikube-path-linux": "/home/blank/.local/state/vs-kubernetes/tools/minikube/linux-amd64/minikube",
        "vs-kubernetes.minikube-show-information-expiration": "2024-06-26T03:01:29.276Z"
    },
    "git.openRepositoryInParentFolders": "never",
    "jupyter.enableExtendedPythonKernelCompletions": true,
    "redhat.telemetry.enabled": true,
    "prisma.showPrismaDataPlatformNotification": false,
    "github.copilot.editor.enableAutoCompletions": true,
    "diffEditor.ignoreTrimWhitespace": false,
    "[markdown]": {
        "editor.defaultFormatter": "rvest.vs-code-prettier-eslint"
    }
}"}
